class ListTests(CliBase):
    FILE = (
        "2024-03-05 Rent -900\n"
        "2024-03-02 groceries -42.50 weekly shop\n"
        "2024-03-01 salary 2500.00 March pay\n"
        "2024-03-02 Groceries -3 snack\n"
    )

    def test_category_filter(self):
        code, out, err = self.run_main(
            ["list", self.write(self.FILE), "--category", "GROCERIES"]
        )
        self.assertEqual((code, err), (0, ""))
        self.assertEqual(
            out, "2024-03-02 groceries -42.50 weekly shop\n2024-03-02 groceries -3.00 snack\n"
        )

    def test_oldest_first_stable_same_day(self):
        code, out, _ = self.run_main(["list", self.write(self.FILE)])
        self.assertEqual(code, 0)
        self.assertEqual(
            out.splitlines(),
            [
                "2024-03-01 salary 2500.00 March pay",
                "2024-03-02 groceries -42.50 weekly shop",
                "2024-03-02 groceries -3.00 snack",
                "2024-03-05 rent -900.00",
            ],
        )

    def test_no_note_no_trailing_space(self):
        out = self.run_main(["list", self.write(self.FILE), "--category", "rent"])[1]
        self.assertEqual(out, "2024-03-05 rent -900.00\n")

    def test_since_until_inclusive(self):
        code, out, _ = self.run_main(
            ["list", self.write(self.FILE), "--since", "2024-03-02", "--until", "2024-03-02"]
        )
        self.assertEqual(code, 0)
        self.assertEqual(len(out.splitlines()), 2)

    def test_json(self):
        code, out, _ = self.run_main(
            ["list", self.write(self.FILE), "--category", "rent", "--json"]
        )
        self.assertEqual(code, 0)
        self.assertEqual(
            json.loads(out),
            [{"date": "2024-03-05", "category": "rent", "amount": "-900.00", "note": ""}],
        )

    def test_json_sorted_oldest_first(self):
        out = self.run_main(["list", self.write(self.FILE), "--json"])[1]
        self.assertEqual(
            [r["date"] for r in json.loads(out)],
            ["2024-03-01", "2024-03-02", "2024-03-02", "2024-03-05"],
        )

    def test_empty_result(self):
        path = self.write(self.FILE)
        self.assertEqual(self.run_main(["list", path, "--category", "x"]), (0, "", ""))
        self.assertEqual(
            self.run_main(["list", path, "--category", "x", "--json"]), (0, "[]\n", "")
        )

    def test_bad_dates_exit_2(self):
        path = self.write(self.FILE)
        for flag in ("--since", "--until"):
            for bad in ("2024-02-30", "03/01/2024", "2024-3-1", "nope"):
                code, out, err = self.run_main(["list", path, flag, bad])
                self.assertEqual((code, out), (2, ""), (flag, bad))
                self.assertTrue(err)

    def test_ledger_error_exit_1(self):
        code, out, err = self.run_main(["list", self.write("2024-01-01 a 1\nbad\n")])
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 2", err)

    def test_missing_file_exit_2(self):
        code, out, _ = self.run_main(["list", os.path.join(self.tmp.name, "nope")])
        self.assertEqual((code, out), (2, ""))

    def test_stdin(self):
        code, out, _ = self.run_main(
            ["list", "-", "--category", "groceries"], stdin=LEDGER.encode("utf-8")
        )
        self.assertEqual((code, out), (0, "2024-03-02 groceries -42.50 weekly shop\n"))


class DateArgTests(unittest.TestCase):
